from book import Chapter
c=Chapter('02')
c.add('''我们说“这里有一个东西”，实际上已经隐含了两个条件：我们能够把它同周围的其他东西区别开来，而且经过一定变化之后，仍然能够认出它。这种稳定并不等于内部什么都没有发生。一个人一直在呼吸、进食、学习，身体里的物质不断更替，我们却仍然认为这是同一个人。

如果没有任何可以保持的关系，就无从谈论一个对象；如果没有任何变化，也无从考察它怎样与其他对象发生作用。存在与变化，因此不是两幅互不相干的画面，而是我们理解同一个过程时的两个方向。''')
c.heading('存在、变化与稳定的构造')
c.src('R48527',0,replacements=[('从根本上讲，宇宙是一个凡事皆有可能，万物皆可存在的环境，对偶子不可能是唯一的存在，但是它确是一个具有稳定复杂结构的事物存在的必须前提','从构造的角度考察，首先要问，一个能够稳定存在、持续演化的复杂结构，需要具备什么条件'),('没有存在性','如果没有可以识别的存在性'),('没有变化性','如果没有变化性'),('所有的事物的属性，都是建立在人类感知的基础上的','我们对事物属性的认识，需要经过感知、测量和相互作用'),('如果事物没有变化，人类就无从感知变化，无从定义这个属性','如果一种属性从不产生可区别的影响，我们就无法通过观察区分它'),('无法感知光的明暗色彩变化','无法通过这些差别感知光的明暗与色彩变化'),('而存在的稳定性和变化的稳定性','\n\n而存在的稳定性和变化规律的稳定性'),('决定了简单结构可以稳定的构成复杂结构','使简单结构有可能稳定地构成复杂结构'),('决定了我们对其的观察结果也是稳定的，可重现的','也为观察结果的稳定和可重现提供了条件')])
c.src('ORIGINAL',60,replacements=[('对应范畴论中的对象','可以借助对象的概念描述'),('世界将是一片混沌','我们就无法识别正在研究什么'),('对应范畴论中的态射','可以借助态射描述相互作用和变化'),('世界将是一片死寂，无法发展，也无法被任何观察者所探测','结构就无法发展，也不能通过相互作用被观察者探测'),('即存在和变化的稳定性，对应恒等态射和态射的复合性','需要考察存在、变化与组合规则的稳定性'),('宇宙将永远停留在最原始的阶段','构造过程就很难积累')])
c.add('''拿积木来想，只有一堆彼此无关的材料，还不足以造出建筑。每一块需要保持一定形状，连接时需要遵守某些关系，连接完成以后又不能立刻散掉。更进一步，已经搭好的小结构，最好还能作为整体参与下一轮组合。这样，建造者才不必每次都从最小材料重新开始。

因此，可构造性关注的不仅是“这两个东西能不能碰到一起”，还包括“碰到一起以后形成什么”“形成的东西能不能保持”“它能不能继续参与新的构造”。一层层积累的条件，在这些问题里逐渐出现。''')
c.heading('为什么想把对象与变化放进同一个基本概念')
c.src('ORIGINAL',46,start='然而，范畴论自身',replacements=[('然而，范畴论自身的基础也并非完美','沿着这个方向，我还想考察范畴论的基本概念能否换一种组织方式'),('范畴的定义还不够简洁','通常的定义把它们分别陈述'),('这是一种二元论的起点，一个终极理论的最基本构件不应该是两个，而应该是一个更简洁、更完美的实体','我的问题是：能不能从一个同时表达存在与变化的构件出发，再说明这两种视角怎样出现')])
c.src('ORIGINAL',47,49,replacements=[('任何定理和结论也都是对偶的','把箭头反转，也能够形成相应的对偶表达'),('从一个全局的不证自明的万有性质','从一种遍及理论结构的关系'),('提升为一个明确的、比对象和态射更基本的实体概念','组织为一个尝试同时描述对象与态射的新概念'),('作为一个终极的初始概念，我们无法探究其内部结构，因为它是一切结构的基础','作为这个构造设想的起点，我们先不预设它必须由哪一种物理材料组成'),('一个对象的身份由它与范畴中所有其他对象的关系所完全决定','一个对象可以通过与其他对象之间成体系的关系来刻画，相关数学结论有其明确的条件')])
c.add('''把它称为对偶体，并不意味着换了一个名字，就已经完成了新的数学基础。这个名字要有用，必须让我们更清楚地写出：哪些构造被允许，哪些关系必须保持，怎样组合，组合以后怎样判断得到的还是同一类对象。

例如，一个计算单元既可以作为保存在文件中的程序，被阅读、复制、比较，也可以在执行时接收输入、产生输出。前一种视角强调它是什么，后一种视角强调它做什么。把两者连起来之后，我们还会追问：不同的内部实现，能不能提供同一种外部功能？同一段内部结构，在不同环境中又会不会表现得不同？''')
c.src('R48840',0,replacements=[('而当将该模块/单元，视作一个范畴的话','如果从结构与关系的角度考察这个模块'),('是不会随着系统演算进程变化的，即它具有指向自身的恒等态射','可以作为一个确定版本保存下来；运行中的状态变化则需要另外描述'),('可以将数据通过极限和余极限操作，完成复杂的数据变化，可以任意组合生成复杂的数据变化','可以完成数据变换，并在接口与条件相容时组合成更复杂的功能'),('我们知道范畴论和计算机软硬件的底层理论lambda演算，以及人类的数理逻辑之间存在等价的关系','范畴论、某些类型化的 lambda 演算与逻辑之间，存在值得利用的对应关系'),('那么如何用','我希望用'),('呢？','。')])
c.heading('内部结构与外部联系，怎样彼此说明')
c.src('R48731',13,start='这个对偶子在不同层级的物理世界中',end='产生出复杂的宇宙万物。',replacements=[('这个对偶子','这种构件'),('分别由不同的物理对象担任，比如在超弦理论中，弦就是这个层级的对偶子，在物质基本元素层次中的原子','可以由不同对象担任，比如物质结构中的原子'),('演变中个体相互关系的递归传递性和组合性','演变中关系的传递性和组合性'),('由对偶子的对偶特性，产生出复杂的宇宙万物','我希望通过研究这些共同条件，理解复杂结构怎样层层出现')],note='嵌入的用户提示段；未使用紧随其后的 AI 肯定回复')
c.add('''这里所说的“同一种构件”，是研究角色上的共同性。一个细胞显然不等于一个人，一个人也不等于一条程序。可是，当我们考察更高一层的组织怎样建立时，可以分别研究这些构件如何保持自身，如何接收与产生影响，如何形成相对稳定的连接。

如果没有这个层级区分，抽象就很容易变成一句空话：万物都有联系，所以万物都一样。真正需要展开的是，哪些联系能够组合，组合后保留了哪些性质，又出现了哪些必须在更高层研究的性质。共同语言应当使这些差别更容易表达，而不是把差别抹掉。''')
c.src('R48731',33,start='如果整个动态演化的复杂系统',end='而我则试图从更基本的范畴论的角度，为整个宇宙（包括生物进化）演化的过程给出一个更基本的解释。',replacements=[('如果整个动态演化的复杂系统，从混沌到有序，从低效率有序到高效率有序，从简单有序结构到复杂有序结构，有一个演化过程','如果一个动态系统能够从简单结构中不断构造出更复杂的结构'),('也会有一个演化/进化过程','也可能在演化中改变'),('对象的稳定性会有一个从低到高的进化过程，态射的多样性，也有一个由寡变多的过程，态射的可复合的概率也会经历一个从低到高的过程，对象推出和拉回的能力也会经历一个从不对称到对称的过程','有些构件变得更稳定，连接方式变得更多，组合成功的条件也可能改善；这些变化能否同时发生，需要在具体系统中考察'),('这个系统中的基本元件的推出和拉回能力，会构造出大量的实例个体','构件的组合与复制能力，可以形成大量实例'),('而DNA的推出拉回能力，构成了DNA的多样性和复制性','而 DNA 的复制、变异和重组，又为多样性和复制性提供了具体机制'),('具有更好的对偶子特性的物种会在竞争中占据主动，更复杂的结构个体占据更多的资源，繁衍更多的个体，这些个体的演化会生成更复杂的结构','能够在相应环境中维持和繁衍的结构，才有条件继续演化；复杂化是其中一种可能，并不意味着越复杂就必然越有优势'),('逐步从从简单到复杂，从低级到高级的过程','随环境与相互作用而变化的过程'),('给出一个更基本的解释','寻找共同的构造解释')])
c.heading('容纳未定，并不需要取消已经确定的规则')
c.src('ORIGINAL',50,53,replacements=[('它将悖论背后的本质，作为整个系统得以运行、演化和涌现的根本原因和动力所在，积极地拥抱和欢迎悖论，而不是规避它','它希望把自指、未定与结构形成的问题纳入研究，而不是遇到边界就停止追问'),('我们可以使用悖论的方式，对对偶体这个基本构件进行精确的数学定义，这通过它对“自指”这一终极探测的回应来体现','一种直观的尝试，是先考察结构怎样回应自指；要成为精确的数学定义，还需要补足相应的规则'),('**自我肯定 → 永远 true**','**能够维持的自我描述**'),('它会始终输出true，表现出稳定的状态。这代表外延涌现确定，呈现稳定存在的同一性','如果描述与构造规则相容，就可能形成可重复识别的稳定关系'),('**自我否定 → true/false 的叠加态**','**不能在当前规则中得到稳定判定的自我描述**'),('它会陷入true和false的叠加态。这代表外延涌现未定，呈现混沌未知的二相性','可能产生循环、矛盾或未定义。不同结果必须分别说明，不能一概当成同一种叠加态'),('前者表现为该事物自指时，自我肯定的概念本身，是存在的基石；后者则表现为该事物自指时，自我否定所引发的悖论，是变化的源泉','前者使我们研究稳定关系，后者使我们研究当前规则的边界以及扩展的可能'),('这种自指的叠加态被“封装”到该元件的内部，它并不破坏外部世界的逻辑一致性，正如一个量子比特的叠加态并不会让宏观计算机崩溃一样','内部尚未确定的过程，可以通过明确的边界与外部已经确定的关系区分开来'),('相反，正是这种内部的、悖论驱动的不确定性，成为了系统“破缺对称性”、涌现出新的层级和结构的动力引擎','接下来需要研究的，是怎样从这些问题中构造新的层级与结构'),('它为整个体系的其它概念和规律提供了终极的解释性，而它本质的内部性质是不可再进一步分析的，因为这种要求超出了范畴论框架的探测能力范围','是否能得到更强的解释与构造能力，要由具体结果说明'),('提供一个第一性的解释','寻找更基本的联系')])
c.add('''可以把这一点放到研究过程里理解。一个模块内部仍然有几个候选方案，不等于外面所有调用它的工作都必须失去规则。它可以清楚说明目前已经保证什么、还有什么不知道，在已知条件下提供功能，同时让内部实现继续改进。

这样，理论就有了一个值得追问的方向：稳定不是演化的结束，而是下一层构造能够开始的条件；变化也不只是破坏稳定，它还可能产生新的稳定关系。要把这个方向展开，就需要继续讨论不动点、最小化、最大化与涌现之间的联系。''')
c.save({'reasoning':'可识别的存在→可探测的变化→组合的稳定→对偶体研究动机→内部实现与外部关系→层级与差异→未定过程的边界','examples':['持续变化的人','积木连接','程序保存与执行','原子细胞人与程序的角色差异','候选模块接口'],'objections':['改名是否等于新数学','抽象是否抹掉学科差异','容纳未定是否允许任意矛盾'],'voice':'大量保留作者 Gemini 逐段论证及原始 Dualoid 结构，严格区分嵌入 AI 回复','status':'初校；形式化仍为研究设想，具体改动可追溯'})
